<script setup lang="ts">import{regexTemplates}from'../../data/regexTemplates';import{useRenameStore}from'../../stores/rename';defineProps<{modelValue:boolean}>();const emit=defineEmits(['update:modelValue']);const s=useRenameStore();function apply(t:typeof regexTemplates[number]){s.useRegex=true;s.setSearch(t.search);s.setReplacement(t.replacement);s.renameExtension=t.renameExtension;emit('update:modelValue',false)}</script><template><el-drawer :model-value="modelValue" title="正则模板" :size="460" class="regex-drawer" @close="$emit('update:modelValue',false)"><div class="intro"><strong>从用途开始选择</strong><p>无需记忆表达式。对照处理前后的示例，选择符合目的的模板即可填入。</p></div><div class="templates"><article v-for="t in regexTemplates" :key="t.title"><div class="template-head"><small>{{t.category}}</small><h3>{{t.title}}</h3></div><p>{{t.purpose}}</p><code><span>{{t.before}}</span><b>→</b><span>{{t.after}}</span></code><el-button type="primary" plain @click="apply(t)">应用模板</el-button></article></div></el-drawer></template><style scoped>.intro{padding:16px;border:1px solid var(--border);border-radius:var(--radius);background:var(--primary-soft)}.intro p{margin:5px 0 0;color:var(--muted);font-size:13px;line-height:1.7}.templates{display:grid;gap:12px;margin-top:14px}article{display:grid;gap:10px;padding:16px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface)}h3,p{margin:0}.template-head{display:flex;align-items:center;gap:10px}.template-head h3{font-size:14px}.template-head small{padding:3px 7px;border-radius:999px;color:var(--primary);background:var(--primary-soft)}article>p{color:var(--text-secondary);font-size:13px;line-height:1.6}code{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:8px;padding:10px;background:var(--surface-soft);border-radius:8px;color:var(--text-secondary);overflow:hidden}code span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}code b{color:var(--primary)}.el-button{justify-self:end}</style>
